import{_ as a,c as i,o as r,ag as t}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Army Evaluation Resources","description":"","frontmatter":{"title":"Army Evaluation Resources"},"headers":[],"relativePath":"general/army-evaluation-resources.md","filePath":"general/army-evaluation-resources.md","lastUpdated":null}'),o={name:"general/army-evaluation-resources.md"};function n(s,e,l,d,p,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="army-evaluation-resources" tabindex="-1">Army Evaluation Resources <a class="header-anchor" href="#army-evaluation-resources" aria-label="Permalink to &quot;Army Evaluation Resources&quot;">​</a></h1><h2 id="army-evaluations-guide" tabindex="-1">Army Evaluations Guide <a class="header-anchor" href="#army-evaluations-guide" aria-label="Permalink to &quot;Army Evaluations Guide&quot;">​</a></h2><p>The resources below, along with practical steps and best practices, aim to supplement that doctrine, helping each participant in the evaluation chain understand their responsibilities, leverage available tools, and appreciate the broader purpose of performance and potential assessments. Anyone in the community can update this and port this up to intellipedia.</p><h3 id="core-references-and-tools" tabindex="-1">Core References and Tools <a class="header-anchor" href="#core-references-and-tools" aria-label="Permalink to &quot;Core References and Tools&quot;">​</a></h3><p><a href="https://www.hrc.army.mil/content/Evaluation%20Systems%20Homepage" target="_blank" rel="noreferrer">HQDA Evals Page: https://www.hrc.army.mil/</a></p><ul><li><a href="#">623–3</a> and <a href="#">PAM 623–3</a> – Primary regulations guiding evaluations.</li></ul><h4 id="officer-evaluation-reports-oer" tabindex="-1">Officer Evaluation Reports (OER): <a class="header-anchor" href="#officer-evaluation-reports-oer" aria-label="Permalink to &quot;Officer Evaluation Reports (OER):&quot;">​</a></h4><ul><li><a href="#">Grade OER</a></li><li><a href="#">Grade OER</a></li><li><a href="#">Grade OER (O6)</a></li><li><a href="#">Officer OER</a> <a href="https://armypubs.army.mil/pub/eforms/DR_a/pdf/ARN17086_A67_10_1A_FINAL.pdf" target="_blank" rel="noreferrer">Direct Link</a></li><li><a href="#">Support Form</a></li></ul><h4 id="noncommissioned-officer-evaluation-reports-ncoer" tabindex="-1">Noncommissioned Officer Evaluation Reports (NCOER): <a class="header-anchor" href="#noncommissioned-officer-evaluation-reports-ncoer" aria-label="Permalink to &quot;Noncommissioned Officer Evaluation Reports (NCOER):&quot;">​</a></h4><ul><li><a href="#">Evaluation Report (SGT).pdf</a> <a href="https://armypubs.army.mil/pub/eforms/DR_a/pdf/DA%20FORM%202166-9-1.pdf" target="_blank" rel="noreferrer">Direct Link</a></li><li><a href="#">(SSG-1SG/MSG)</a></li><li><a href="#">(CSM-SGM)</a></li><li><a href="#">Support Form</a></li><li><a href="#">Form 2166-9 Series Guide</a> Academic Evaluation Reports (AER): DA Form 1059 Series – Used for academic performance evaluations.</li></ul><h4 id="counseling-tools" tabindex="-1">Counseling Tools: <a class="header-anchor" href="#counseling-tools" aria-label="Permalink to &quot;Counseling Tools:&quot;">​</a></h4><ul><li><a href="#">Counseling Form</a> <a href="https://armypubs.army.mil/ProductMaps/PubForm/Details.aspx?PUB_ID=1026753" target="_blank" rel="noreferrer">Direct Link</a></li><li><a href="#">Counseling Checklist/Record</a></li></ul><h4 id="ai-enabled-online-resources" tabindex="-1">AI Enabled Online Resources: <a class="header-anchor" href="#ai-enabled-online-resources" aria-label="Permalink to &quot;AI Enabled Online Resources:&quot;">​</a></h4><ul><li><a href="https://www.armified.com/" target="_blank" rel="noreferrer">Armified</a> – A free (beta) platform offering templates and sample approaches.</li><li><a href="https://rapidepr.com/" target="_blank" rel="noreferrer">RapidEPR</a> – A long-standing resource for multi-branch evaluations.</li><li><a href="/ai-ml/evaluation-ai-prompt.html">AI Prompt</a> – Template to structure prompts for Large Language Models, assisting in drafting initial bullet comments or narratives.</li></ul><h3 id="rater" tabindex="-1">Rater <a class="header-anchor" href="#rater" aria-label="Permalink to &quot;Rater&quot;">​</a></h3><p>The Rater sets the tone for objective, honest performance assessments. Through regular counseling, effective communication, and using support forms, the Rater identifies strengths, weaknesses, and developmental needs of the rated Soldier.</p><p><strong>Key Responsibilities:</strong></p><ul><li><p>Conduct initial and periodic performance counseling sessions using the <a href="/general/army-evaluation-resources.html">COUNSELING FORM</a> and NCO Counseling Checklist/Record for NCOs.</p></li><li><p>Accurately document performance, aligning narrative comments and bullets with observed achievements and adherence to Army Values.</p></li><li><p>For OERs and NCOERs, ensure rated Soldiers receive timely guidance on improving their performance and expanding their professional potential.</p></li></ul><p><strong>Most Qualified (MQ) Ratings:</strong> The Rater’s profile limits how often they can award MQ ratings. The MQ label signifies exceptional performance and potential among peers. To maintain credibility and keep MQ meaningful, the Rater must be strategic:</p><ol><li><p><strong>Consistency and Fairness:</strong> Reward truly standout performers. Avoid rating inflation.</p></li><li><p><strong>Developmental Focus:</strong> Use counseling and mentorship to build stronger Soldiers, ensuring top achievers emerge naturally.</p></li><li><p><strong>Long-Term Profile Management:</strong> Resist the urge to give everyone top marks; reserving MQ for the few who merit it enhances the Rater’s credibility.</p></li><li><p><strong>Army Values and Leadership Attributes:</strong> Consider ethics, leadership, technical skill, and potential for advancement, not just immediate results.</p></li></ol><p>By managing the profile judiciously and communicating standards clearly, the Rater ensures the evaluation process remains fair, credible, and aligned with Army standards.</p><h3 id="senior-rater" tabindex="-1">Senior Rater <a class="header-anchor" href="#senior-rater" aria-label="Permalink to &quot;Senior Rater&quot;">​</a></h3><p>The Senior Rater provides a broader perspective, focusing on the rated Soldier’s long-term potential for increased responsibility. While the Rater assesses day-to-day performance, the Senior Rater looks ahead, evaluating how well the Soldier might serve at higher levels.</p><p><strong>Key Responsibilities:</strong></p><ul><li><p>Offer a big-picture assessment, integrating the Rater’s input with an understanding of Army needs.</p></li><li><p>Distinguish among strong, average, and weaker performers by highlighting those most ready for advancement.</p></li><li><p>Help maintain the integrity of MQ assignments by reviewing the Rater’s profile and ensuring MQ ratings align with a Soldier’s true long-term potential.</p></li></ul><p><strong>Strategic Guidance:</strong></p><ul><li><p>Consider how each rated Soldier fits into future operational and leadership roles.</p></li><li><p>Use the support forms and counseling input provided by the Rater to inform your evaluation, ensuring consistency across the rating chain.</p></li><li><p>Reinforce the importance of honest, direct language, and accurate assessments.</p></li></ul><p>By focusing on potential and providing an overarching viewpoint, the Senior Rater ensures Soldiers are correctly identified for advancement, professional opportunities, and further development.</p><h3 id="supplementary-reviewer" tabindex="-1">Supplementary Reviewer <a class="header-anchor" href="#supplementary-reviewer" aria-label="Permalink to &quot;Supplementary Reviewer&quot;">​</a></h3><p>TIP: Rater &gt; Senior Rater &gt; Supplementary Reviewer &gt; Rated NCO &gt;  Senior Rater  &gt; HQDA. (See AR 623-3 ch. 2 – 14)</p><p>The Supplementary Reviewer adds an extra layer of oversight in scenarios that require additional scrutiny to preserve fairness and objectivity.</p><p><strong>When Required:</strong></p><ul><li><p>If no uniformed Army rating officials are on the rating chain, ensuring compliance with Army standards.</p></li><li><p>In &quot;Relief for Cause&quot; cases, when directed by the senior rater or an external official.</p></li><li><p>For certain Academic Evaluation Reports (AERs) with “Failed to Achieve Course Standards” or “Did Not Graduate” entries.</p></li></ul><p><strong>Key Responsibilities:</strong></p><ul><li><p>Verify the accuracy and fairness of the report without adding new evaluative comments.</p></li><li><p>Maintain the integrity of the evaluation system by confirming that rating officials adhered to regulatory guidance.</p></li><li><p>For OERs (67-10 series), enter supplementary review data in Part II (f-blocks); for NCOERs (2166-9 series), enter in Part II (c-blocks); for 67-10-4 OERs, prepare a separate memorandum.</p></li></ul><p>The Supplementary Reviewer acts as a safeguard, ensuring evaluations reflect the Soldier’s performance and potential free from conflict of interest or undue influence.</p><h3 id="rated-soldier" tabindex="-1">Rated Soldier <a class="header-anchor" href="#rated-soldier" aria-label="Permalink to &quot;Rated Soldier&quot;">​</a></h3><p>The Rated Soldier is the individual whose performance and potential are being documented. Understanding the evaluation process, forms, and criteria can empower the Rated Soldier to take charge of their development.</p><p><strong>Key Responsibilities:</strong></p><ul><li><p>Engage fully in counseling sessions. Ask for clarity, seek feedback, and act on guidance provided by the Rater.</p></li><li><p>Use support forms to highlight accomplishments, special projects, training, and achievements. This input helps your rating chain produce an accurate, comprehensive evaluation.</p></li><li><p>Understand how MQ ratings work. Recognize that not everyone can receive MQ and that sustained excellence, adherence to Army Values, and continual self-improvement bolster your chances.</p></li><li><p>Review your final evaluation thoroughly. If discrepancies arise, know that you can pursue an appeals process with documented evidence.</p></li></ul><h3 id="frequently-asked-questions-faq" tabindex="-1">Frequently Asked Questions (FAQ) <a class="header-anchor" href="#frequently-asked-questions-faq" aria-label="Permalink to &quot;Frequently Asked Questions (FAQ)&quot;">​</a></h3><p>The following FAQs provide a snapshot of common concerns and clarifications drawn from the doctrine and references uploaded. While these answers serve as an accessible guide, always consult the most current versions of <em>623–3 Evaluation Reporting System (ERS)</em> and <em>PAM 623–3 Evaluation Reporting System (ERS)</em> for definitive policy and procedural guidance.</p><ul><li><p><a href="https://www.hrc.army.mil/content/18837" target="_blank" rel="noreferrer">HQDA NCOER FAQ</a></p></li><li><p><a href="https://www.hrc.army.mil/content/18945" target="_blank" rel="noreferrer">HQDA OER FAQ</a></p></li></ul><hr><h3 id="_1-what-are-the-primary-types-of-evaluation-reports-used-in-the-army" tabindex="-1">1. What are the primary types of evaluation reports used in the Army? <a class="header-anchor" href="#_1-what-are-the-primary-types-of-evaluation-reports-used-in-the-army" aria-label="Permalink to &quot;1. What are the primary types of evaluation reports used in the Army?&quot;">​</a></h3><ul><li><p><strong>Officer Evaluation Reports (OERs):</strong> DA Form 67-10 series, tailored for company-grade, field-grade, strategic-grade, and general officers.</p></li><li><p><strong>Noncommissioned Officer Evaluation Reports (NCOERs):</strong> DA Form 2166-9 series, assessing NCO performance and potential at various ranks (SGT, SSG-1SG/MSG, CSM/SGM).</p></li><li><p><strong>Academic Evaluation Reports (AERs):</strong> DA Form 1059 series, documenting academic performance at Army schools or civilian institutions.</p></li></ul><hr><h3 id="_2-when-are-evaluation-reports-typically-completed" tabindex="-1">2. When are evaluation reports typically completed? <a class="header-anchor" href="#_2-when-are-evaluation-reports-typically-completed" aria-label="Permalink to &quot;2. When are evaluation reports typically completed?&quot;">​</a></h3><p>Evaluation reports are generated for multiple reasons, including:</p><ul><li><p><strong>Regular Reports:</strong> At scheduled intervals based on rank and component.</p></li><li><p><strong>Change of Rater:</strong> When a rated Soldier’s immediate supervisor changes.</p></li><li><p><strong>Change of Duty:</strong> When the rated Soldier’s principal duty or position changes.</p></li><li><p><strong>Relief for Cause:</strong> To document removal from a duty position under unfavorable circumstances.</p></li><li><p><strong>Annual Reports:</strong> Required at set periods for certain categories of Soldiers.</p></li></ul><hr><h3 id="_3-how-does-the-rated-soldier-participate-in-the-evaluation-process" tabindex="-1">3. How does the rated Soldier participate in the evaluation process? <a class="header-anchor" href="#_3-how-does-the-rated-soldier-participate-in-the-evaluation-process" aria-label="Permalink to &quot;3. How does the rated Soldier participate in the evaluation process?&quot;">​</a></h3><p>The rated Soldier should:</p><ul><li><p>Attend and engage in counseling sessions with the Rater, using tools like the <a href="/general/army-evaluation-resources.html">COUNSELING FORM</a> and NCO Counseling Checklist to track performance goals.</p></li><li><p>Contribute input through support forms (e.g., OER and NCOER support forms), highlighting achievements, specific duties, and noteworthy accomplishments throughout the rating period.</p></li><li><p>Review the completed evaluation report for accuracy and appeal the report if discrepancies or perceived injustices arise.</p></li></ul><hr><h3 id="_4-what-are-the-responsibilities-of-the-rater-and-senior-rater" tabindex="-1">4. What are the responsibilities of the Rater and Senior Rater? <a class="header-anchor" href="#_4-what-are-the-responsibilities-of-the-rater-and-senior-rater" aria-label="Permalink to &quot;4. What are the responsibilities of the Rater and Senior Rater?&quot;">​</a></h3><ul><li><p><strong>Rater:</strong> Conducts regular performance counseling, observes and records the Soldier’s day-to-day performance, and prepares objective assessments with clear, consistent standards.</p></li><li><p><strong>Senior Rater:</strong> Evaluates the Soldier’s long-term potential for positions of increased responsibility, considering not just immediate performance but suitability for future leadership roles.</p></li></ul><hr><h3 id="_5-what-is-the-significance-of-most-qualified-mq-ratings-and-how-are-they-determined" tabindex="-1">5. What is the significance of “Most Qualified (MQ)” ratings and how are they determined? <a class="header-anchor" href="#_5-what-is-the-significance-of-most-qualified-mq-ratings-and-how-are-they-determined" aria-label="Permalink to &quot;5. What is the significance of “Most Qualified (MQ)” ratings and how are they determined?&quot;">​</a></h3><p>MQ ratings indicate truly standout performance and potential. Both raters and senior raters manage their profiles, limiting how many MQ assessments they can grant. This ensures MQ remains meaningful and signals a Soldier’s exceptional distinction among peers. By understanding these constraints, Soldiers recognize that MQ is earned through consistent excellence, strong leadership qualities, adherence to Army Values, and demonstrated capacity for future responsibility.</p><hr><h3 id="_6-when-is-a-supplementary-review-required" tabindex="-1">6. When is a supplementary review required? <a class="header-anchor" href="#_6-when-is-a-supplementary-review-required" aria-label="Permalink to &quot;6. When is a supplementary review required?&quot;">​</a></h3><p>A supplementary review is necessary when:</p><ul><li><p>No uniformed Army rating officials are present in the chain.</p></li><li><p>A “Relief for Cause” evaluation is directed by the senior rater or someone outside the rating chain.</p></li><li><p>Certain conditions in AERs (e.g., “Failed to Achieve Course Standards” or “Did Not Graduate”) trigger additional oversight to ensure fairness and objectivity.</p></li></ul><hr><h3 id="_7-can-evaluation-reports-be-modified-after-submission" tabindex="-1">7. Can evaluation reports be modified after submission? <a class="header-anchor" href="#_7-can-evaluation-reports-be-modified-after-submission" aria-label="Permalink to &quot;7. Can evaluation reports be modified after submission?&quot;">​</a></h3><p>Yes. Factual errors or new, relevant information may warrant an amendment or addendum to the original report. Procedures for requesting and processing amendments are outlined in the applicable regulations, ensuring accuracy and completeness of the Soldier’s record.</p><hr><h3 id="_8-what-should-a-soldier-do-if-they-disagree-with-their-evaluation-report" tabindex="-1">8. What should a Soldier do if they disagree with their evaluation report? <a class="header-anchor" href="#_8-what-should-a-soldier-do-if-they-disagree-with-their-evaluation-report" aria-label="Permalink to &quot;8. What should a Soldier do if they disagree with their evaluation report?&quot;">​</a></h3><p>If the Soldier believes the report is inaccurate or unfair, they may initiate the appeals process. This involves submitting a written appeal and supporting evidence. The appropriate authority reviews the appeal, which may uphold, modify, or invalidate the contested report.</p><hr><h3 id="_9-how-do-these-evaluations-support-the-soldier-s-career-progression" tabindex="-1">9. How do these evaluations support the Soldier’s career progression? <a class="header-anchor" href="#_9-how-do-these-evaluations-support-the-soldier-s-career-progression" aria-label="Permalink to &quot;9. How do these evaluations support the Soldier’s career progression?&quot;">​</a></h3><p>Evaluations guide developmental counseling, inform promotion boards, influence future assignments, and shape professional development opportunities. A strong evaluation history, supported by substantiated accomplishments and leadership potential, assists Soldiers in advancing their careers and contributing more effectively to the Army’s mission.</p><h3 id="terms" tabindex="-1">Terms <a class="header-anchor" href="#terms" aria-label="Permalink to &quot;Terms&quot;">​</a></h3><ul><li>Appeal **</li></ul><p>The procedure taken by the rated Soldier or another interested party to correct administrative or substantive type errors for evaluation reports accepted for inclusion in the rated officer’s or NCO’s AMHRR.</p><ul><li>Appointed duties **</li></ul><p>Additional responsibilities not normally associated with the duty description.</p><ul><li>Army competitive category **</li></ul><p>RA officers in the basic branches. This category does not include the specialty branches of the Chaplain’s Corps, Judge Advocate General’s Corps, or the AMEDD.</p><ul><li>Attributes **</li></ul><p>Shape how an individual behaves and learns in his or her environment. The leader attributes are character, presence, and intellect. These attributes capture the values and identity of the leader (character); the leader’s outward appearance, demeanor, actions, and words (presence); and the mental and social faculties the leader applies in the act of leading (intellect). Attributes affect the actions that leaders perform. Good character, solid presence, and keen intellect enable the core leader competencies to be performed with greater effect.</p><ul><li>Broadening **</li></ul><p>The purposeful expansion of a Leader’s capabilities and understanding provided through opportunities internal and external to the Army throughout their career, gained through experiences and/or education in different organizational cultures and environments resulting in a Leader who can operate up to and including the strategic level in multiple environments.</p><ul><li>Bullet comments **</li></ul><p>Short, concise, to-the-point comments starting with action words (verbs) or possessive pronouns (his or her). Bullet comments will not be longer than two lines, preferably one, and no more than one bullet to a line.</p><ul><li>Calendar year **</li></ul><p>A period that is 365 days, or 366 days if the Leap Year date, 29 February, is included.</p><ul><li>Chain of command **</li></ul><p>The succession of military commanders, superior to subordinate, through which command is exercised. Normally, commanders evaluate commanders.</p><ul><li>Chain of supervision **</li></ul><p>The individuals (military and/or civilian) involved in providing operational, functional, and/or technical supervision of a rated Soldier.</p><ul><li>Competence **</li></ul><p>The knowledge, skills, and abilities necessary to be an expert in the current duty assignment and to perform adequately in other assignments within the MOS, when required. Competence is both technical and tactical and includes reading, writing, speaking, and basic mathematics. It also includes sound judgment, ability to weigh alternatives, form objective options, and make good decisions. Closely allied with competence is the constant desire to better, to listen and learn more, and to do each task completely to the best of one’s ability. Competence is exemplified through learning, growing, setting standards and achieving them, creating and innovating, taking prudent risks, and never settling for less than the best. The demonstration of a commitment to excellence.</p><ul><li>Commander’s or Commandant’s Inquiry **</li></ul><p>Investigation into a Soldier’s evaluation report made by an official in the chain of command/supervisory chain above the designated rating officials involved in the allegations to determine if an illegality, injustice, or regulatory violation has occurred. The appointing official for a Commander’s or Commandant’s Inquiry into an OER will normally be the commander, commandant, or civilian supervisor who rates the senior rater. The appointing official for an NCOER will normally be the commander, commandant, or civilian supervisor who rates the reviewer.</p><ul><li>Complete the record **</li></ul><p>An optional type of evaluation report intended to update a Soldier’s file with performance and potential information that has not previously been documented in the Soldier’s evaluation history since the time of the most recent evaluation report. MILPER messages clearly specify the criteria for complete the record reports (“THRU” date and required receipt date at HQDA).</p><ul><li>Dual supervision **</li></ul><p>A situation in which an officer or warrant officer who, during the entire period of evaluation, is assigned separate responsibilities and receives supervision from two different chains of command or supervision. This provision does not apply to NCO rating schemes, NCOERs, or AERs.</p><ul><li>Evaluation report timeliness **</li></ul><p>A resulting equation (percentage of reports submitted on time) that is correlated to individual senior raters on those reports and reflects submission to HQDA within regulatory guidelines.</p><ul><li>FROM date **</li></ul><p>The beginning date of the period covered; the day following the “THRU” (ending) date of the most recent evaluation report period.</p><ul><li>HQDA electronically generated label **</li></ul><p>A label placed over the rater’s and senior rater’s box check portion on a DA Form 67–10 series. Used only for OERs for officers (2LT through COL) and warrant officers (WO1 through CW4). It shows a comparison of the block check on the OER to all box checks for a given grade in a rater’s and senior rater’s profile. This does not apply to NCOERs or AERs.</p><ul><li>Intermediate rater **</li></ul><p>A supervisor in a rated officer’s chain of command or supervision between the rater and senior rater. This level of supervision may be in the rated officer’s organization or in a separate organization if under dual supervision.</p><ul><li>Leadership **</li></ul><p>Characterized by a complex mix of organizational, situational, and mission demands on a leader who applies personal qualities, abilities, and experiences to exert influence on the organization, its people, the situation, and the unfolding mission. Difficult and complex situations are the proving ground for leaders expected to make consistent, timely, effective, and just decisions. An Army leader is anyone who, by virtue of assumed role or assigned responsibility, inspires and influences people to accomplish organizational goals. Army leaders motivate people both inside and outside the chain of command to pursue actions, focus thinking, and shape decisions for the greater good of the organization.</p><ul><li>Nonrated time **</li></ul><p>Time periods when the rated Soldier cannot be evaluated by the rating officials. Such time periods include, but are not limited to, school attendance, in-transit travel, hospitalization or patient status, convalescent leave, leave periods of 30 days or more, and periods when the rater has not met minimum qualifications. Periods such as breaks in service or time spent in an IRR, Ready Reserve, or ING status are not ratable periods; therefore, these periods will appear as gaps in a rated Soldier’s evaluation report history.</p><ul><li>Performance counseling **</li></ul><p>Planned method to inform Soldiers about their duties and expected performance standards and provide feedback on actual performance. Soldiers’ performance includes appearance, conduct, mission accomplishment, and the manner in which duties are carried out. Honest feedback lets Soldiers know how well they are performing compared to the expected standards.</p><ul><li>Performance evaluation **</li></ul><p>Assessments of how well the rated Soldier met his or her duty requirements and adhered to Army professional leadership standards. Performance is evaluated by observing a rated Soldier’s actions, demonstrated behavior, and results in terms of adherence to the Army Values and his or her responsibilities. Due regard is given to the experience level of the rated Soldier, efforts made, and results achieved.</p><ul><li>Period of report **</li></ul><p>Time period covered by an evaluation report, which includes rated and nonrated time. The period begins the day following the “THRU” (ending) date of the most recent evaluation report and ends on the day of the event causing the current report to be rendered or the last day of supervision/duty day before a Soldier’s departure.</p><ul><li>Physical fitness and military bearing **</li></ul><p>Consists of two components with various subcomponents. Physical fitness is the physical and mental ability to accomplish the mission, that is, combat readiness. Total fitness includes weight control, diet and nutrition, smoking cessation, control of substance abuse, stress management, and physical training. It covers strength, endurance, stamina, flexibility, speed, agility, coordination, and balance. Soldiers are responsible for their own physical fitness and that of their subordinates. Military bearing consists of posture, dress, overall appearance, and manner of physical movement. Bearing also includes an outward display of inner feelings, fears, and overall confidence and enthusiasm. An inherent responsibility of all leaders is concern with Soldiers’ military bearing and making on-the-spot corrections, as needed.</p><ul><li>Pooling **</li></ul><p>Elevating the rating chain beyond the senior rater’s ability to know the Soldier, in an attempt to provide an elevated assessment protection for a specific group runs counter to the intent of the evaluation system.</p><ul><li>Potential evaluation **</li></ul><p>An assessment of the rated Soldier’s ability, compared with that of other Soldiers of the same grade, to perform in positions of greater responsibility and/or higher grades.</p><ul><li>Rated Soldier **</li></ul><p>A rated officer, warrant officer, or NCO.</p><ul><li>Rated time **</li></ul><p>Time when a rated Soldier has been assigned under a valid rating chain for the purposes of counseling, guidance, and evaluation of performance and potential.</p><ul><li>Rater **</li></ul><p>First-line supervisor of the rated Soldier who is designated as the rater on the rating scheme. Primary role is that of evaluating, focusing on performance, and performance counseling. Conducts face-to-face performance counseling with the rated Soldier.</p><ul><li>Rater’s comments **</li></ul><p>Comments provided by the rater. They are brief, concise, and reflect the rater’s observation of the rated Soldier’s performance in the areas described in the evaluation report.</p><ul><li>Rating chain **</li></ul><p>The chain of command/supervision that provides counseling and evaluation of a Soldier. It includes the rater, senior rater, and reviewer.</p><ul><li>Senior rater **</li></ul><p>The second-level supervisor or designated official in the rating chain responsible for assessing potential and overall performance. Provides a broad perspective on the rated Soldier’s capability to perform duties beyond the current assignment and recommends future development and/or promotion potential.</p><ul><li>Senior rater’s comments **</li></ul><p>Comments provided by the senior rater. They should address potential and overall performance, giving a broader perspective than the rater’s comments and focus on the rated Soldier’s ability to assume increased responsibility.</p><ul><li>Total Army School System (TASS) **</li></ul><p>The organizational structure within the Army that provides training and education for the Total Army.</p><ul><li>Unobserved period **</li></ul><p>A time period when the rater or senior rater did not directly observe the rated Soldier’s performance or conduct, including absences due to leave, hospitalization, or other reasons.</p><ul><li>Unit evaluation report **</li></ul><p>A report prepared for a Soldier by the unit’s chain of command, typically issued at the end of a specified period, evaluating the Soldier’s performance and potential.</p><ul><li>Validity period **</li></ul><p>The period during which an evaluation report is considered to be accurate and reliable. Typically includes a specific timeframe during which the report was prepared and evaluated.</p><ul><li>Work-related competencies **</li></ul><p>Skills, knowledge, and abilities related to the tasks and responsibilities of a specific job or duty assignment.</p><ul><li>Work-related values **</li></ul><p>The ethical standards, beliefs, and principles that guide behavior and decision-making in a work environment.</p>',150)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
